define("local_airpay_manager/manager_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var openDecideForm = function(requestid, decision, returnFocus) {
        var verb = decision === "rejected" ? "Reject" : "Approve";
        var modalForm = new ModalForm({
            formClass: "local_airpay_manager\\form\\decide_request_dynamic_form",
            args: {requestid: requestid, decision: decision},
            modalConfig: {title: verb + " enrolment request"},
            returnFocus: returnFocus
        });
        modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
            var detail = event.detail || {};
            var warn = detail.enrolwarning || "";
            Notification.addNotification({
                message: warn ? "Decision saved. Note: " + warn : "Request " + decision + ".",
                type: warn ? "warning" : "success"
            });
            window.location.reload();
        });
        modalForm.show();
    };

    var openCreateAllocationForm = function(returnFocus) {
        var modalForm = new ModalForm({
            formClass: "local_airpay_manager\\form\\create_allocation_dynamic_form",
            args: {},
            modalConfig: {title: "Allocate course to direct report", large: true},
            returnFocus: returnFocus
        });
        modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function() {
            Notification.addNotification({message: "Course allocated.", type: "success"});
            window.location.reload();
        });
        modalForm.show();
    };

    var openBulkAllocateForm = function(returnFocus) {
        var modalForm = new ModalForm({
            formClass: "local_airpay_manager\\form\\bulk_allocate_dynamic_form",
            args: {},
            modalConfig: {title: "Bulk-assign course to direct reports", large: true},
            returnFocus: returnFocus
        });
        modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
            var detail = event.detail || {};
            var succ = detail.succeeded_count || 0;
            var skip = detail.skipped_count || 0;
            var fail = detail.failed_count || 0;
            var msg = "Allocated to " + succ + " user(s).";
            if (skip > 0) msg += " " + skip + " skipped (already had).";
            if (fail > 0) msg += " " + fail + " failed.";
            Notification.addNotification({
                message: msg,
                type: fail > 0 ? "warning" : "success"
            });
            window.location.reload();
        });
        modalForm.show();
    };

    var confirmDeleteAllocation = function(allocid, name, returnFocus) {
        Notification.deleteCancelPromise(
            "Cancel allocation",
            "Cancel the allocation of \"" + name + "\"? The user's enrolment is not removed.",
            "Cancel allocation", returnFocus).then(function() {
            Ajax.call([{
                methodname: "local_airpay_manager_delete_allocation",
                args: {id: allocid}
            }])[0].then(function() {
                Notification.addNotification({message: "Allocation cancelled.", type: "success"});
                window.location.reload();
                return null;
            }).catch(Notification.exception);
            return true;
        }, function() { return null; });
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var requestid = parseInt(trigger.dataset.requestid || "0", 10);
        var decision = trigger.dataset.decision || "approved";
        var allocid = parseInt(trigger.dataset.allocid || "0", 10);
        var name = trigger.dataset.name || "this allocation";
        switch (action) {
            case "decide-request":      event.preventDefault(); openDecideForm(requestid, decision, trigger); break;
            case "create-allocation":   event.preventDefault(); openCreateAllocationForm(trigger); break;
            case "bulk-allocate":       event.preventDefault(); openBulkAllocateForm(trigger); break;
            case "delete-allocation":   event.preventDefault(); confirmDeleteAllocation(allocid, name, trigger); break;
        }
    };

    var reloadTable = function(mountId, extraArgs) {
        var mount = document.getElementById(mountId);
        if (!mount) return;
        mount.dataset.extraArgs = JSON.stringify(extraArgs);
        mount.dispatchEvent(new CustomEvent("airpay-datatable:reload", {bubbles: true}));
    };

    return {
        init: function(config) {
            config = config || {};
            document.addEventListener("click", handleClick);
            if (config.page === "requests") {
                var sel = document.getElementById("ap-mgr-status");
                if (sel) sel.addEventListener("change", function() {
                    reloadTable("ap-mgr-requests-table", {status: sel.value || "pending"});
                });
            }
            if (config.page === "allocations") {
                var sel2 = document.getElementById("ap-mgr-alloc-status");
                if (sel2) sel2.addEventListener("change", function() {
                    reloadTable("ap-mgr-alloc-table", {status: sel2.value || "all"});
                });
            }
        }
    };
});
